text:
.account-indicator {
  display: none;
  box-sizing: border-box;
  background-color: var(--account-color, var(--folder-color-inbox));
  border-radius: 3px;
  inline-size: 3px;
  block-size: 1rem;
  margin-inline-start: 3px;
  margin-inline-end: var(--account-indicator-inline-end);

  [data-mode="smart"] & {
    margin-inline-start: 4px;
    margin-inline-end: -4px;
  }
}
